import xml.etree.ElementTree as ET
from xml.dom import minidom
from zipfile import ZipFile

def dump_docx_xml(docx_path, output_dir="."):
    """
    Extracts and pretty-prints the key XML files from a docx.
    Writes them as readable .xml files you can open in any editor.

    Files written:
        document_pretty.xml   ← body, paragraphs, w:ins, w:del, footnote refs
        footnotes_pretty.xml  ← footnote content text
        settings_pretty.xml   ← numStart, numRestart settings
    """
    files_to_dump = [
        ("word/document.xml",  "document_pretty.xml"),
        ("word/footnotes.xml", "footnotes_pretty.xml"),
        ("word/settings.xml",  "settings_pretty.xml"),
    ]

    with ZipFile(docx_path) as z:
        available = z.namelist()
        for zip_path, out_name in files_to_dump:
            if zip_path not in available:
                print(f"[SKIP] {zip_path} not found in docx")
                continue

            raw_bytes = z.read(zip_path)

            # Pretty print using minidom
            parsed   = minidom.parseString(raw_bytes)
            pretty   = parsed.toprettyxml(indent="  ", encoding="utf-8")

            out_path = f"{output_dir}/{out_name}"
            with open(out_path, "wb") as f:
                f.write(pretty)

            print(f"[OK] Written: {out_path}")

    print("\nDone. Open the _pretty.xml files in VS Code or any text editor.")
    print("Search for:  w:ins   w:del   w:footnoteReference   to find what you need.")


# ── also print a focused console summary of every footnote ref and its context ──
def print_footnote_ref_context(docx_path):
    """
    Prints every w:footnoteReference found in document.xml, showing:
      - the footnote ID
      - whether it is inside w:ins / w:del / plain text
      - the w:id of the enclosing w:ins (if any)
      - the text of the enclosing paragraph (first 80 chars)
    """
    W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

    def w(name):
        return f"{{{W}}}{name}"

    ins_tags = {w("ins"), w("moveTo")}
    del_tags = {w("del"), w("moveFrom")}

    with ZipFile(docx_path) as z:
        root = ET.fromstring(z.read("word/document.xml"))

        footnote_content = {}
        try:
            fn_root = ET.fromstring(z.read("word/footnotes.xml"))
            for fn in fn_root.findall(f"{{{W}}}footnote"):
                fn_id = fn.attrib.get(w("id"), "")
                texts = [t.text or "" for t in fn.findall(f".//{{{W}}}t")]
                footnote_content[fn_id] = "".join(texts)[:60]
        except KeyError:
            pass

    body = root.find(f"{{{W}}}body")

    print("\n" + "=" * 80)
    print(f"FOOTNOTE REFERENCE CONTEXT DUMP: {docx_path}")
    print("=" * 80)
    print(f"{'fn_id':>6}  {'location':>10}  {'ins_id':>8}  {'para_text_preview'}")
    print(f"{'─'*6}  {'─'*10}  {'─'*8}  {'─'*50}")

    def get_para_text(p_elem):
        texts = [t.text or "" for t in p_elem.findall(f".//{{{W}}}t")]
        return "".join(texts)[:80]

    def walk_para(p_elem):
        """Walk a paragraph and find all footnote refs with their context."""

        def _walk(elem, ins_group=None, in_del=False):
            tag = elem.tag

            if tag in del_tags:
                for child in elem:
                    _walk(child, ins_group=ins_group, in_del=True)
                return

            if tag in ins_tags:
                gid = elem.attrib.get(w("id"), str(id(elem)))
                for child in elem:
                    _walk(child, ins_group=gid, in_del=in_del)
                return

            if tag == w("r"):
                ref = elem.find(w("footnoteReference"))
                if ref is not None:
                    fn_id = ref.attrib.get(w("id"), "?")
                    if in_del:
                        location = "DELETED"
                    elif ins_group:
                        location = "INSERTED"
                    else:
                        location = "existing"
                    ins_label = ins_group if ins_group else "—"
                    para_preview = get_para_text(p_elem)
                    fn_preview   = footnote_content.get(fn_id, "")
                    print(f"  {fn_id:>6}  {location:>10}  {ins_label:>8}  para: {para_preview[:50]!r}")
                    print(f"  {'':>6}  {'':>10}  {'':>8}  fn:   {fn_preview!r}")
                return

            for child in elem:
                _walk(child, ins_group=ins_group, in_del=in_del)

        _walk(p_elem)

    def walk_body(elem):
        tag = elem.tag
        if tag == w("p"):
            walk_para(elem)
            return
        for child in elem:
            walk_body(child)

    walk_body(body)
    print("=" * 80)


